// Tree as adjacency: id -> array of child ids. Root is 0.
const children = { 0:[1,2], 1:[3,4], 2:[5], 3:[], 4:[6,7], 5:[], 6:[], 7:[] };
const PER_BOX = 5; // microseconds of layout work per box
// Ancestors carrying `contain: layout` (a boundary caps invalidation at its own subtree).
const contained = new Set([4]); // node 4 has contain: layout

function subtreeSize(node) {
  // count node + all descendants
  let n = 1;
  for (const c of children[node]) n += subtreeSize(c);
  return n;
}

function reflowCost(changedNode) {
  // A layout change reflows the changed node's whole subtree.
  // If the changed node itself sits on/under a contain:layout boundary,
  // invalidation still cannot escape upward — but here we only model the
  // DOWNWARD blast from changedNode, which is always its own subtree size.
  // TODO: return (#invalidated boxes) * PER_BOX
}

// Changing node 1 invalidates subtree {1,3,4,6,7} = 5 boxes
console.assert(reflowCost(1) === 25, 'node1');
// Changing node 4 invalidates {4,6,7} = 3 boxes
console.assert(reflowCost(4) === 15, 'node4');
// Changing root 0 invalidates all 8 boxes
console.assert(reflowCost(0) === 40, 'root');

console.log(reflowCost(1), reflowCost(4), reflowCost(0));
